// العلوم — الصف السابع — الجزء الأول. ترتيب الوحدات والدروس وأرقام الصفحات من فهرس كتاب الطالب (وزارة التربية والتعليم الفلسطينية).
window.UNITS=[{"id": "U1", "part": 1, "t": "الوحدة الأولى: خصائص الكائنات الحية", "les": [{"t": "التغذية", "pg": 4, "pts": ["تحصل الكائنات الحيّة على حاجتها من الغذاء الضروري لعملياتها الحيوية، إمّا بتحويل الموادّ الأوّليّة البسيطة كالماء وثاني أكسيد الكربون باستغلال ضوء الشمس إلى كربوهيدرات من خلال عملية البناء الضوئي، كما في النباتات والطحالب وبعض أنواع البكتيريا، وتسمّى كائنات ذاتية التغذية (منتجات الغذاء). (ص 5)", "وإمّا أن تحصل عليه جاهزًا من كائنات حيّة أخرى، كالفطريات والحيوانات والإنسان، وتسمّى كائنات غير ذاتية التغذية. (ص 5)", "يُعدّ النشا من السكريات معقدة التركيب، ويتمّ بناؤه من اتحاد مئات من جزيئات سكر بسيط ناتجة من عملية البناء الضوئي. (ص 5)", "يفرز فطر العفن إنزيمات هاضمة على الموادّ الغذائية فيحلّلها، ومن ثمّ يمتصّ نواتج التحلّل لاستخدامها في عملياته الحيوية. (ص 8)"], "terms": [["كائنات ذاتية التغذية", "كائنات تحوّل الموادّ الأوّليّة البسيطة إلى كربوهيدرات من خلال عملية البناء الضوئي، وتسمّى منتجات الغذاء. (ص 5)"], ["كائنات غير ذاتية التغذية", "كائنات تحصل على غذائها جاهزًا من كائنات حيّة أخرى، كالفطريات والحيوانات والإنسان. (ص 5)"], ["الترمّم", "تحلّل الموادّ العضوية والفضلات وجثث الكائنات الحيّة بعد موتها، وهو شكل من أشكال التغذية غير الأساسية. (ص 8)"]], "facts": [["النباتات الخضراء ذاتية التغذية.", 1], ["الفطريات تقوم بالبناء الضوئي.", 0], ["ينتج البناء الضوئي الغلوكوز والأكسجين.", 1]], "ex": [["كيف يحصل فطر العفن على غذائه؟", "يفرز إنزيمات هاضمة على الموادّ الغذائية فيحلّلها، ثمّ يمتصّ نواتج التحلّل. (ص 8)"], ["أيّ الكائنات الحية الآتية يصنف من الكائنات الحية غير ذاتية التغذية غير الأساسية؟ (تمرين من الكتاب، ص 28)", "الخميرة"], ["ما صنف التغذية في دودة الأسكارس؟ (تمرين من الكتاب، ص 28)", "تطفل داخلي"], ["أيّ الكائنات الحية الآتية يتغذى على (النباتات) فقط؟ (تمرين من الكتاب، ص 28)", "الجراد"]], "id": "U1L1", "img": [4, 5, 6, 7, 8], "bmc": [["أيّ الكائنات الحية الآتية يصنف من الكائنات الحية غير ذاتية التغذية غير الأساسية؟", ["الخميرة", "النمر", "الفأر", "الإنسان"], 0, 28], ["ما صنف التغذية في دودة الأسكارس؟", ["تطفل داخلي", "تطفل خارجي", "ترمم", "التغذية الذاتية"], 0, 28], ["أيّ الكائنات الحية الآتية يتغذى على (النباتات) فقط؟", ["الجراد", "القط", "الأسد", "الدجاج"], 0, 28], ["أيّ المواد الآتية تلزم لحدوث عملية البناء الضوئي؟", ["ثاني أكسيد الكربون", "الغلوكوز", "الأكسجين", "أول أكسيد الكربون"], 0, 28]], "bq": [["اتفق زوجان على أن تتم تغذية طفلهما بالرضاعة الطبيعية خلال الأشهر الأولى من عمره، وعدم الاستعانة بالحليب الصناعي، ما رأيك في ذلك؟ فسّر إجابتك.", "قرار صحيح؛ فحليب الأم غذاء متكامل يناسب الطفل ويقوّي مناعته.", 28], ["يربي أحمد أنواعًا من أسماك الزينة في حوض زجاجي، اقترح عليه والده بأن يضع طحالب في الحوض. ما الهدف من ذلك؟", "الطحالب تقوم بالبناء الضوئي فتطلق الأكسجين اللازم لتنفس الأسماك، وتكون غذاءً لها.", 29]]}, {"t": "الأيض", "pg": 9, "pts": ["تحدث في أجسام الكائنات الحيّة مجموعة من التفاعلات الكيميائية؛ تفاعلات يتمّ فيها تحويل موادّ بسيطة إلى موادّ معقّدة كما في البناء الضوئي ويطلق عليها عملية البناء، وتفاعلات يتمّ فيها تحطيم الموادّ المعقّدة إلى موادّ بسيطة ويطلق عليها عملية الهدم. (ص 9)", "أطلق العلماء على هذه التفاعلات بنوعيها البناء والهدم اسم الأيض. (ص 10)", "تستمدّ الكائنات الحيّة طاقتها بتحطيم الموادّ العضوية، بوجود الأكسجين أو عدمه، ومن هذه العمليات التنفّس الذي يقسم إلى تنفّس هوائي وتخمّر. (ص 10)", "تُعدّ الخميرة من الفطريات الرمّية، ويمكنها العيش في بيئة خالية من الأكسجين، فهي تستمدّ الطاقة من تخمّر الموادّ العضوية. (ص 11)"], "terms": [["الأيض", "التفاعلات الكيميائية بنوعيها البناء والهدم في أجسام الكائنات الحيّة. (ص 10)"], ["البناء", "تحويل موادّ بسيطة إلى موادّ معقّدة كما في البناء الضوئي. (ص 9)"], ["الهدم", "تحطيم الموادّ المعقّدة إلى موادّ بسيطة. (ص 9)"]], "facts": [["التخمّر يحتاج إلى الأكسجين.", 0], ["ينتج التنفس الهوائي طاقة أكثر من التخمّر.", 1], ["انتفاخ العجين سببه غاز ثاني أكسيد الكربون.", 1]], "ex": [["ما نسبة ثاني أكسيد الكربون في الغلاف الجوي؟", "0.04% تقريبًا، وتُعدّ الكائنات الحيّة من المنتجات الرئيسة له من خلال التنفّس. (ص 10)"], ["أيّ الآتي يحقق الهدف من عملية التنفس؟ (تمرين من الكتاب، ص 28)", "إنتاج الطاقة"], ["أيّ الآتية يعد من نواتج عملية التنفس الهوائي ؟ (تمرين من الكتاب، ص 28)", "ثاني أكسيد الكربون"]], "id": "U1L2", "img": [9, 10, 11, 12], "bmc": [["أيّ الآتي يحقق الهدف من عملية التنفس؟", ["إنتاج الطاقة", "استهلاك ثاني أكسيد الكربون", "إنتاج الغلوكوز", "استهلاك الطاقة"], 0, 28], ["أيّ الآتية يعد من نواتج عملية التنفس الهوائي ؟", ["ثاني أكسيد الكربون", "الأكسجين", "الغلوكوز", "الكحول"], 0, 28]]}, {"t": "النمو", "pg": 13, "pts": ["يحدث الانقسام في معظم خلايا جسم الحيوان خلال فترة نموّه؛ إذ تمرّ الخلية بمجموعة من التغيّرات تؤدّي إلى إنتاج خليتين، وهذا ما يسمّى بالانقسام الخلوي. (ص 13)", "في النباتات خلايا في القمم النامية للجذر والساق تدعى الخلايا المولّدة متخصّصة بعملية الانقسام لنموّ النبتة. (ص 13)", "يمرّ الإنسان خلال حياته في مراحل عمرية مختلفة: الطفولة، والمراهقة، والرشد، وسنّ الأمان، والشيخوخة. (ص 14)", "تُعدّ مرحلة المراهقة إحدى مراحل النموّ التي تقع بين مرحلتي الطفولة والرشد، وتحدث أغلب تغيّراتها نتيجة التغيّر في إفرازات الغدد الصمّاء (اللاقنوية). (ص 15–16)"], "terms": [["النموّ", "الزيادة في كتلة جسم الكائن الحيّ وحجمه. (ص 13)"], ["الانقسام الخلوي", "مجموعة تغيّرات تمرّ بها الخلية تؤدّي إلى إنتاج خليتين. (ص 13)"], ["المراهقة", "مرحلة نموّ تقع بين مرحلتي الطفولة والرشد. (ص 15)"]], "facts": [["المراهقة من مراحل نمو الإنسان.", 1], ["انتفاخ البالون نمو.", 0]], "ex": [["أين توجد الخلايا المولّدة في النبات؟", "في القمم النامية في كلّ من الجذر والساق. (ص 13)"], ["ما اسم المرحلة العمرية للإنسان الواقعة بين ١٢ - ٢٠ سنة؟ (تمرين من الكتاب، ص 28)", "المراهقة"]], "id": "U1L3", "img": [13, 14, 15, 16, 17], "bmc": [["ما اسم المرحلة العمرية للإنسان الواقعة بين ١٢ - ٢٠ سنة؟", ["المراهقة", "الرشد", "الطفولة", "النضج"], 0, 28]], "bq": [["علّل: تحدث العديد من التغيرات النفسية على المراهق.", "بسبب التغيرات الهرمونية والجسمية في مرحلة البلوغ.", 29]]}, {"t": "الحركة", "pg": 18, "pts": ["تمتلك الكائنات الحيّة الدقيقة وسائل مختلفة للحركة؛ بهدف تمكينها من القيام بالعمليات الحيوية. (ص 18)", "بعض هذه الكائنات يمتلك زوائد قصيرة (أهداب)، وبعضها يمتلك زوائد طويلة. (ص 18)"], "terms": [["الأهداب", "زوائد قصيرة تستخدمها بعض الكائنات الدقيقة في الحركة كالبراميسيوم. (ص 18)"]], "facts": [["النبات يتحرك نحو الضوء.", 1], ["النباتات لا تتحرك إطلاقًا.", 0]], "ex": [["لماذا يميل نبات الشرفة نحو النافذة؟", "بسبب الانتحاء الضوئي نحو الضوء."], ["ما نوع الحركة المتمثلة في عملية فتح وإغلاق الثغور في النباتات؟ (تمرين من الكتاب، ص 28)", "موضعية"]], "id": "U1L4", "img": [18, 19], "bmc": [["ما نوع الحركة المتمثلة في عملية فتح وإغلاق الثغور في النباتات؟", ["موضعية", "سيتوبلازمية", "انتقالية", "أميبية"], 0, 28]]}, {"t": "الإخراج", "pg": 20, "pts": ["تتنوّع فضلات الحيوانات الراقية فمنها موادّ نيتروجينية، ومنها غازات، ومنها سوائل، وبالتالي تمتلك هذه الحيوانات وسائل إخراجية مختلفة. (ص 20)", "ينتج من عمليات الأيض فضلات، يلجأ الجسم إلى التخلّص منها؛ لأنّ تراكمها يسبّب أضرارًا وتسمّمًا للكائن الحيّ. (ص 22)", "يتمثّل دور الجهاز البولي في تنقية الدم من بعض الفضلات النيتروجينية وإخراجها إلى خارج الجسم في البول. (ص 22)", "لا تحتاج النباتات إلى أجهزة إخراجية كالحيوان؛ لأنّ كمية فضلاتها قليلة وتجمّعها بطيء، وتتخلّص منها بسقوط الأوراق، وعن طريق الثغور. (ص 22)"], "terms": [["الجهاز البولي", "جهاز ينقّي الدم من بعض الفضلات النيتروجينية ويخرجها في البول. (ص 22)"]], "facts": [["الكليتان من أعضاء الإخراج.", 1], ["الرئتان تُخرجان الأكسجين فضلاتٍ.", 0], ["العرق من طرق الإخراج.", 1]], "ex": [["لماذا لا تحتاج النباتات إلى أجهزة إخراجية؟", "لأنّ كمية فضلاتها قليلة وتجمّعها بطيء، وتستخدم نواتج بعض العمليات الحيوية في عمليات أخرى. (ص 22)"], ["ما العضو المسؤول عن إخراج ثاني أكسيد الكربون من جسم الإنسان؟ (تمرين من الكتاب، ص 28)", "الرئتين"]], "id": "U1L5", "img": [20, 21, 22], "bmc": [["ما العضو المسؤول عن إخراج ثاني أكسيد الكربون من جسم الإنسان؟", ["الرئتين", "القلب", "الجلد", "الكلية"], 0, 28]], "bq": [["علّل: تلجأ الكائنات الحية إلى التخلص من فضلاتها النيتروجينية وبسرعة.", "لأنها مواد سامّة تضرّ الجسم إذا تراكمت فيه.", 29], ["علّل: لا تحتاج النباتات إلى جهاز إخراجي متخصص.", "لأن فضلاتها قليلة، وتتخلص منها عبر الثغور أو تخزنها في أوراق تتساقط.", 29]]}, {"t": "الاستجابة", "pg": 23, "pts": ["تمتلك الكائنات الحيّة وسائل مختلفة للتكيّف مع مؤثّرات البيئة المحيطة؛ فالأميبا لا تمتلك خلايا متخصّصة، لكنّها تنجذب للضوء وتبتعد عن الحرارة الشديدة. (ص 23)", "الكائنات الحيّة الراقية كالإنسان تمتلك خلايا متخصّصة تمكّنها من الاستجابة بسرعة. (ص 23)", "النباتات لا تمتلك خلايا أو أجهزة متخصّصة للاستجابة، ولذلك تكون استجابتها بطيئة، إلّا أنّ هناك حالات استجابة سريعة كما في نبات دوّار الشمس. (ص 24)"], "terms": [["الاستجابة", "سلوك يقوم به الكائن الحيّ كوسيلة للتكيّف مع مؤثّرات البيئة المحيطة. (ص 23)"]], "facts": [["سحب اليد عن الإبريق الساخن استجابة.", 1], ["الكائنات الحية لا تستجيب للمؤثرات.", 0]], "ex": [["ما المنبه والاستجابة: نغلق أعيننا عند ضوء قوي.", "المنبه: الضوء القوي، الاستجابة: إغلاق العين."]], "id": "U1L6", "img": [23, 24, 25]}, {"t": "التكاثر", "pg": 26, "pts": ["نظرًا لتنوّع الكائنات الحيّة تنوّعت طرق تكاثرها، فهناك التكاثر اللاجنسي، والتكاثر الجنسي. (ص 26)", "التكاثر اللاجنسي لا يحتاج إلى وجود أزواج (ذكر وأنثى)، مثل: الانشطار في الأميبا، والتبرعم في الخميرة، والتجزئة في نجم البحر، والتكاثر الخضري في النباتات كالتطعيم أو الترقيد أو الفسائل. (ص 27)", "يُعدّ التكاثر الجنسي من أنواع التكاثر التي تحتاج إلى وجود أزواج (ذكر وأنثى). (ص 27)"], "terms": [["التكاثر اللاجنسي", "تكاثر لا يحتاج إلى وجود أزواج (ذكر وأنثى). (ص 27)"], ["التكاثر الجنسي", "تكاثر يحتاج إلى وجود أزواج (ذكر وأنثى). (ص 27)"], ["التبرعم", "طريقة تكاثر لاجنسي في الخميرة. (ص 27)"]], "facts": [["الخميرة تتكاثر بالتبرعم.", 1], ["التكاثر اللاجنسي يحتاج أبوين.", 0], ["زراعة عُقل العنب تكاثر خضري.", 1]], "ex": [["كيف يتكاثر نجم البحر بالتجزئة؟", "يُقطّع إلى أجزاء، وكلّ جزء يحتوي على القرص المركزي يصبح قادرًا على تكوين حيوان جديد. (ص 27)"], ["ما الكائن الحي الذي يتكاثر بعملية الانشطار؟ (تمرين من الكتاب، ص 28)", "اليوغلينا"]], "id": "U1L7", "img": [26, 27, 28, 29, 30, 31], "bmc": [["ما الكائن الحي الذي يتكاثر بعملية الانشطار؟", ["اليوغلينا", "العنب", "المشروم", "الخميرة"], 0, 28]], "bq": [["أكمل الجدول بنوع التكاثر (جنسي/لاجنسي) وطريقته: الزيتون، البندورة، الدجاج، البكتيريا، الخميرة.", "الزيتون: جنسي بالبذور، ولاجنسي بالعُقل. البندورة: جنسي بالبذور. الدجاج: جنسي بالبيض. البكتيريا: لاجنسي بالانشطار. الخميرة: لاجنسي بالتبرعم.", 29]]}]}, {"id": "U2", "part": 1, "t": "الوحدة الثانية: الذرة والتفاعل الكيميائي", "les": [{"t": "تركيب الذرة", "pg": 32, "pts": ["تتكوّن المادة من وحدات صغيرة جدًّا لا ترى بالعين المجرّدة تسمّى الذرّات. (ص 32)", "تتكوّن الذرّة من نواة تتركّز فيها جسيمات موجبة الشحنة تسمّى البروتونات، وجسيمات متعادلة الشحنة تسمّى النيوترونات، وحول النواة مستويات تدور فيها جسيمات سالبة الشحنة تسمّى الإلكترونات. (ص 33)", "كتلة البروتون تساوي كتلة النيوترون وتساوي 1840 كتلة الإلكترون. (ص 33)"], "terms": [["الذرّات", "وحدات صغيرة جدًّا لا ترى بالعين المجرّدة تتكوّن منها المادة. (ص 32)"], ["البروتونات", "جسيمات موجبة الشحنة في النواة. (ص 33)"], ["النيوترونات", "جسيمات متعادلة الشحنة في النواة. (ص 33)"], ["الإلكترونات", "جسيمات سالبة الشحنة تدور في مستويات حول النواة. (ص 33)"]], "facts": [["الإلكترونات داخل النواة.", 0], ["البروتون موجب الشحنة.", 1], ["الذرة متعادلة كهربائيًا.", 1]], "ex": [["ذرة فيها 6 بروتونات. كم إلكترونًا فيها؟", "6 إلكترونات، لأن الذرة متعادلة."], ["ما أصغر مكونات الذرّة؟ (تمرين من الكتاب، ص 44)", "الإلكترون"], ["ما عدد النيوترونات في نواة ذرّة الفسفور الذي عدده الذري ١٥ وعدده الكتلي ٣١؟ (تمرين من الكتاب، ص 44)", "١٦"], ["ما عدد الإلكترونات لذرة الصوديوم (العدد الذري ١١، العدد الكتلي ٢٣)؟ (تمرين من الكتاب، ص 44)", "١١"]], "id": "U2L1", "img": [32, 33], "bmc": [["ما أصغر مكونات الذرّة؟", ["الإلكترون", "البروتون", "النيوترون", "النواة"], 0, 44], ["ما عدد النيوترونات في نواة ذرّة الفسفور الذي عدده الذري ١٥ وعدده الكتلي ٣١؟", ["١٦", "٤٦", "٣١", "١٥"], 0, 44], ["ما عدد الإلكترونات لذرة الصوديوم (العدد الذري ١١، العدد الكتلي ٢٣)؟", ["١١", "١٠", "٢٣", "١٢"], 0, 44]], "bq": [["فسّر تفسيرًا علميًّا: الذرّة متعادلة كهربائيًّا.", "لأن عدد البروتونات الموجبة في النواة يساوي عدد الإلكترونات السالبة حولها.", 44]]}, {"t": "هوية العنصر", "pg": 34, "pts": ["يمثّل العدد الذرّي عدد البروتونات في نواة ذرّة العنصر، وبما أنّ الذرّة متعادلة كهربائيًّا يكون عدد الإلكترونات مساويًا لعدد البروتونات. (ص 34)", "يمثّل العدد الكتلي مجموع عدد البروتونات والنيوترونات داخل نواة الذرّة. (ص 34)", "يتّسع المستوى الأوّل لإلكترونين، والثاني لـ 8 إلكترونات، والثالث لـ 18 إلكترونًا. (ص 36)", "اشتُقّت رموز العناصر من أسمائها اللاتينية (العناصر المكتشفة قديمًا كالذهب والفضة) أو الإنجليزية (المكتشفة لاحقًا كالمغنيسيوم والكالسيوم). (ص 37)"], "terms": [["العدد الذرّي", "عدد البروتونات = عدد الإلكترونات. (ص 34)"], ["العدد الكتلي", "عدد البروتونات + عدد النيوترونات. (ص 34)"]], "facts": [["رمز الأكسجين O.", 1], ["العدد الكتلي = عدد الإلكترونات فقط.", 0], ["العدد الذري يحدّد نوع العنصر.", 1]], "ex": [["ذرّة الكلور عددها الذرّي 17 وعددها الكتلي 35، فما عدد نيوتروناتها؟", "عدد النيوترونات = العدد الكتلي – العدد الذرّي = 35 – 17 = 18 نيوترونًا. (ص 35)"]], "id": "U2L2", "img": [34, 35, 36, 37, 38]}, {"t": "مركبات مهمة في حياتنا", "pg": 39, "pts": ["توجد المادة في الطبيعة من حولنا بأشكال مختلفة، فقد تكون على شكل عناصر، أو مركّبات، أو مخاليط. (ص 39)", "يوجد في حياتنا كثير من المركّبات الكيميائية التي نستخدمها في مجالات متعدّدة، كالطبّ، والغذاء، والصيدلة، والزراعة. (ص 39)", "تدلّ الصيغة الجزيئية لمركّب ما على عدد ذرّات العناصر المكوّنة له ونوعها. (ص 40)"], "terms": [["الصيغة الجزيئية", "تدلّ على عدد ذرّات العناصر المكوّنة للمركّب ونوعها. (ص 40)"]], "facts": [["الماء مركّب من الهيدروجين والأكسجين.", 1], ["ملح الطعام عنصر.", 0]], "ex": [["ما الصيغة الجزيئية لملح الطعام؟", "NaCl. (ص 39)"], ["ما الصيغة الجزيئية لسكر المائدة؟", "C12H22O11. (ص 39)"], ["عمّ تعبّر الصيغة الجزيئية للمركب؟ (تمرين من الكتاب، ص 44)", "عدد الذرات المكونة له ونوعها"], ["أي العناصر الآتية لا تدخل في تركيب سكر المائدة (C₁₂H₂₂O₁₁)؟ (تمرين من الكتاب، ص 44)", "الهيليوم"]], "id": "U2L3", "img": [39, 40], "bmc": [["عمّ تعبّر الصيغة الجزيئية للمركب؟", ["عدد الذرات المكونة له ونوعها", "عدد الذرات المكونة له فقط", "نوع الذرات المكونة له فقط", "حجم الذرات المكونة له فقط"], 0, 44], ["أي العناصر الآتية لا تدخل في تركيب سكر المائدة (C₁₂H₂₂O₁₁)؟", ["الهيليوم", "الهيدروجين", "الأكسجين", "الكربون"], 0, 44], ["ما عدد ذرات الكلور المكونة لصيغة مركب كلوريد الألومنيوم (AlCl₃)؟", ["٣", "١", "٢", "٤"], 0, 44]]}, {"t": "التفاعلات الكيميائية", "pg": 41, "pts": ["يُعدّ التغيّر الفيزيائي تغيّرًا في شكل المادة دون التأثير على تركيبها الكيميائي. (ص 42)", "يُعدّ التغيّر الكيميائي تغيّرًا في التركيب الكيميائي للمادة وينتج عنه مادة أو موادّ جديدة ذات خواصّ مختلفة، يطلق عليه اسم التفاعل الكيميائي. (ص 42)", "يُعبّر عن التفاعل الكيميائي بمعادلة كيميائية تبيّن المواد المتفاعلة والمواد الناتجة والعوامل المساعدة. (ص 43)"], "terms": [["التغيّر الفيزيائي", "تغيّر في شكل المادة دون التأثير على تركيبها الكيميائي. (ص 42)"], ["التفاعل الكيميائي", "تغيّر في التركيب الكيميائي للمادة ينتج عنه مادة أو موادّ جديدة ذات خواصّ مختلفة. (ص 42)"]], "facts": [["تصاعد غاز من علامات التفاعل الكيميائي.", 1], ["في التفاعل لا تتكوّن مواد جديدة.", 0]], "ex": [["عبّر بمعادلة لفظية عن البناء الضوئي.", "الماء + ثاني أكسيد الكربون ← سكر الغلوكوز + الأكسجين (بوجود الضوء والكلوروفيل). (ص 43)"], ["ماذا تمثل المعادلة الكيميائية؟ (تمرين من الكتاب، ص 44)", "المواد المتفاعلة والمواد الناتجة وظروف التفاعل"]], "id": "U2L4", "img": [41, 42, 43, 44, 45, 46], "bmc": [["ماذا تمثل المعادلة الكيميائية؟", ["المواد المتفاعلة والمواد الناتجة وظروف التفاعل", "المواد المتفاعلة", "المواد الناتجة", "ظروف التفاعل"], 0, 44]], "bq": [["يتحلل الماء كهربائيًّا إلى مكوناته من الأكسجين والهيدروجين، عبّر عن التفاعل بمعادلة كيميائية لفظية مبينًا المواد المتفاعلة والمواد الناتجة وظروف التفاعل.", "ماء ← (تيار كهربائي) ← هيدروجين + أكسجين. المتفاعل: الماء. النواتج: الهيدروجين والأكسجين. الظرف: التيار الكهربائي.", 44]]}]}, {"id": "U3", "part": 1, "t": "الوحدة الثالثة: الحركة وقوانين نيوتن", "les": [{"t": "الحركة الانتقالية", "pg": 47, "pts": ["تتحرّك الأجسام في مسارات مستقيمة أحيانًا وفي مسارات غير مستقيمة أحيانًا أخرى. (ص 47)", "إذا عاد الجسم إلى نقطة البداية فإنّ الإزاحة تساوي صفرًا. (ص 48)", "عندما يقطع الجسم المتحرّك في خطّ مستقيم إزاحات متساوية خلال أزمنة متساوية فإنّ سرعته ثابتة. (ص 51)"], "terms": [["الإزاحة", "تساوي صفرًا إذا عاد الجسم إلى نقطة البداية. (ص 48)"], ["السرعة الثابتة", "قطع إزاحات متساوية خلال أزمنة متساوية في خطّ مستقيم. (ص 51)"]], "facts": [["وحدة السرعة م/ث.", 1], ["الإزاحة دائمًا أكبر من المسافة.", 0]], "ex": [["ركض أسعد 800 م ثمّ 400 م ثمّ 300 م ثمّ 500 م. ما المسافة؟", "المسافة = 800 + 400 + 300 + 500 = 2000 متر. (ص 48)"], ["ما المفهوم الذي يعبّر عن التغير في السرعة في وحدة الزمن؟ (تمرين من الكتاب، ص 63)", "التسارع"], ["ما إزاحة سيارة قطعت مسافة ١٠٠ م باتجاه الشرق، ثم رجعت إلى نفس نقطة انطلاقها؟ (تمرين من الكتاب، ص 63)", "صفر"], ["كيف تصف جسمًا يظهر تغيّر موضعه في فترات زمنية متساوية بمسافات متزايدة (الشكل في الكتاب)؟ (تمرين من الكتاب، ص 63)", "يتسارع"]], "id": "U3L1", "img": [47, 48, 49, 50, 51], "bmc": [["ما المفهوم الذي يعبّر عن التغير في السرعة في وحدة الزمن؟", ["التسارع", "السرعة المتوسطة", "المسافة", "الإزاحة"], 0, 63], ["ما إزاحة سيارة قطعت مسافة ١٠٠ م باتجاه الشرق، ثم رجعت إلى نفس نقطة انطلاقها؟", ["صفر", "١٠٠ م", "٢٠٠م", "٣٠٠ م"], 0, 63], ["كيف تصف جسمًا يظهر تغيّر موضعه في فترات زمنية متساوية بمسافات متزايدة (الشكل في الكتاب)؟", ["يتسارع", "يتباطأ", "يسير بسرعة ثابتة", "يتباطأ ثم يتسارع"], 0, 63, "bookimg/runners.webp"], ["تتحرك سيارة بسرعة ٢٠ م /ث، فما دلالة ذلك؟", ["تقطع مسافة مقدارها ٢٠م في كل ثانية", "تتزايد المسافة التي تقطعها بمقدار ٢٠ م في كل ثانية", "تتزايد سرعتها بمقدار ٢٠ م في كل ثانية", "تتناقص سرعتها بمقدار ٢٠ م في كل ثانية"], 0, 64]]}, {"t": "التسارع الثابت", "pg": 52, "pts": ["التسارع هو الكمية الفيزيائية الناتجة عن حساب النسبة بين التغيّر في السرعة إلى التغيّر في الزمن. (ص 52)", "التسارع (ت) = (ع2 – ع1) ÷ ز. (ص 52)", "أثناء تدحرج الكرة على المستوى إلى الأسفل فإنّ سرعتها تزداد بمرور الزمن ويكون تسارعها موجبًا، بعكس تدحرجها للأعلى. (ص 54)"], "terms": [["التسارع", "النسبة بين التغيّر في السرعة إلى التغيّر في الزمن. (ص 52)"]], "facts": [["وحدة التسارع م/ث².", 1], ["السيارة التي تسير بسرعة ثابتة لها تسارع كبير.", 0]], "ex": [["سيارة سباق تتزايد سرعتها من 4 م/ث إلى 36 م/ث خلال 4 ثوانٍ. ما تسارعها؟", "ت = (36 – 4) ÷ 4 = 8 م/ث². (ص 52)"], ["ما مقدار تسارع سيارة تحركت من السكون فوصلت سرعتها بعد زمن مقداره ٣ ثوانٍ إلى ١٢ م/ث؟ (تمرين من الكتاب، ص 63)", "٤ م/ث²"], ["يتحرك جسم بسرعة مقدارها ٢٠ م/ث، أثرت عليه قوة فتوقف خلال ٤ ثوانٍ، ما تسارع هذا الجسم بوحدة م/ث²؟ (تمرين من الكتاب، ص 64)", "-٥"]], "id": "U3L2", "img": [52, 53, 54], "bmc": [["ما مقدار تسارع سيارة تحركت من السكون فوصلت سرعتها بعد زمن مقداره ٣ ثوانٍ إلى ١٢ م/ث؟", ["٤ م/ث²", "٠٫٢٥ م/ث²", "٣٦ م/ث²", "١٢ م/ث²"], 0, 63], ["يتحرك جسم بسرعة مقدارها ٢٠ م/ث، أثرت عليه قوة فتوقف خلال ٤ ثوانٍ، ما تسارع هذا الجسم بوحدة م/ث²؟", ["-٥", "٥", "٨٠", "-٨٠"], 0, 64]]}, {"t": "القانون الأول لنيوتن", "pg": 55, "pts": ["ينصّ القانون الأوّل لنيوتن على: يبقى الجسم على حالته من حيث السكون أو الحركة ما لم تؤثّر فيه قوة محصّلة تغيّر من مقدار سرعته أو اتجاهها أو كليهما. (ص 56)", "بسبب عجز الجسم عن تغيير حالته الحركية من تلقاء نفسه وممانعته لأيّ مؤثّر خارجي، سُمّي بقانون القصور الذاتي. (ص 56)"], "terms": [["القصور الذاتي", "عجز الجسم عن تغيير حالته الحركية من تلقاء نفسه وممانعته لأيّ مؤثّر خارجي. (ص 56)"]], "facts": [["حزام الأمان يحمينا بسبب القصور الذاتي.", 1], ["الجسم الساكن يتحرك وحده دون قوة.", 0]], "ex": [["لماذا يندفع الركاب للأمام عند توقف الحافلة فجأة؟", "بسبب القصور الذاتي: تميل أجسامهم للاستمرار في الحركة."]], "id": "U3L3", "img": [55, 56]}, {"t": "القانون الثاني لنيوتن", "pg": 57, "pts": ["ينصّ القانون الثاني لنيوتن: إذا أثّرت قوة محصّلة في جسم ما، فإنّها تكسبه تسارعًا يتناسب طرديًّا مع القوة، وعكسيًّا مع كتلته. (ص 59)", "الصيغة الرياضية للقانون الثاني لنيوتن: ق محصّلة = ك × ت. (ص 59)", "يُعرّف النيوتن بأنّه القوة اللازمة لإكساب جسم كتلته 1 كغم تسارعًا مقداره 1 م/ث². (ص 60)", "إذا سقط الجسم سقوطًا حرًّا فإنّ الجاذبية تكسبه تسارعًا ثابتًا هو تقريبًا 10 م/ث². (ص 58)"], "terms": [["النيوتن", "القوة اللازمة لإكساب جسم كتلته 1 كغم تسارعًا مقداره 1 م/ث². (ص 60)"]], "facts": [["ق = ك × ت.", 1], ["زيادة الكتلة مع ثبات القوة تزيد التسارع.", 0]], "ex": [["أثّرت قوة مقدارها 20 نيوتن في جسم فأكسبته تسارعًا مقداره 10 م/ث². ما كتلته؟", "ك = ق ÷ ت = 20 ÷ 10 = 2 كغم. (ص 60)"], ["سوسن كتلتها 30 كغم تكتسب تسارعًا 0.8 م/ث². ما قوة السحب؟", "ق = 30 × 0.8 = 24 نيوتن. (ص 60)"], ["ما وحدة قياس القوة؟ (تمرين من الكتاب، ص 63)", "كغم.م/ث²"], ["ما كتلةُ العربة التي إذا أثرت عليها قوة مقدارها ٢٠ نيوتن أكسبتها تسارعًا مقداره ٥ م/ث²؟ (تمرين من الكتاب، ص 63)", "٤ كغم"]], "id": "U3L4", "img": [57, 58, 59, 60], "bmc": [["ما وحدة قياس القوة؟", ["كغم.م/ث²", "كغم.م.ث²", "كغم/(م.ث²)", "(كغم.م)/ث"], 0, 63], ["ما كتلةُ العربة التي إذا أثرت عليها قوة مقدارها ٢٠ نيوتن أكسبتها تسارعًا مقداره ٥ م/ث²؟", ["٤ كغم", "٥ كغم", "٢ كغم", "١٠٠ كغم"], 0, 63], ["ما مقدار القوة (ق) التي تجعل عربة كتلتها ٢ كغم تتحرك بتسارع مقداره ٢م/ث²؟", ["٤ نيوتن", "١ نيوتن", "٢ نيوتن", "٨ نيوتن"], 0, 63, "bookimg/cart.webp"]]}, {"t": "القانون الثالث لنيوتن", "pg": 61, "pts": ["عندما يؤثّر جسم بقوة في جسم آخر، فإنّ الجسم الآخر لا بدّ أن يؤثّر فيه بقوة مساوية لها في المقدار ومعاكسة لها في الاتجاه. (ص 62)", "تؤثّر كلّ قوة في جسم يختلف عن الجسم الذي تؤثّر فيه القوة الأخرى، بحيث لا تلغي أيّ من القوتين تأثير الأخرى. (ص 62)", "ينصّ القانون الثالث لنيوتن على: لكلّ قوة فعل قوة ردّ فعل مساوية لها في المقدار ومعاكسة لها في الاتجاه. (ص 62)"], "terms": [["القانون الثالث لنيوتن", "لكلّ قوة فعل قوة ردّ فعل مساوية لها في المقدار ومعاكسة لها في الاتجاه. (ص 62)"]], "facts": [["انطلاق الصاروخ مثال على القانون الثالث.", 1], ["ردّ الفعل أكبر دائمًا من الفعل.", 0]], "ex": [["كيف يتقدّم السبّاح؟", "يدفع الماء للخلف (فعل) فيدفعه الماء للأمام (ردّ فعل)."], ["أيّ العبارات الآتية صحيحة في حال اصطدام شاحنة كبيرة بسيارة صغيرة؟ (تمرين من الكتاب، ص 64)", "مقدار القوة المؤثرة على كل من المركبتين متساوٍ"], ["يمثّل الشكل رجلًا وفيلًا يقفان على مزلاجتين في حالة سكون، دفع الرجل الفيل بقوة مقدارها (ق). قارن بين القوة المؤثرة على الرجل والقوة المؤثرة على الفيل من حيث المقدار والاتجاه: (تمرين من الكتاب، ص 64)", "متساويتان في المقدار ومتعاكستان في الاتجاه"], ["في الشكل، إذا كانت كتلة الفيل 10 أضعاف كتلة الرجل، وتسارع الرجل بمقدار 10 م/ث²، فما مقدار تسارع الفيل؟ (تمرين من الكتاب، ص 64)", "1 م/ث²"]], "id": "U3L5", "img": [61, 62, 63, 64, 65, 66, 67, 68], "bmc": [["أيّ العبارات الآتية صحيحة في حال اصطدام شاحنة كبيرة بسيارة صغيرة؟", ["مقدار القوة المؤثرة على كل من المركبتين متساوٍ", "مقدار القوة التي أثرت بها الشاحنة على السيارة أكبر", "يكون أثر التصادم على الشاحنة أكبر", "يكون أثر التصادم على المركبتين متساويًا"], 0, 64], ["يمثّل الشكل رجلًا وفيلًا يقفان على مزلاجتين في حالة سكون، دفع الرجل الفيل بقوة مقدارها (ق). قارن بين القوة المؤثرة على الرجل والقوة المؤثرة على الفيل من حيث المقدار والاتجاه:", ["متساويتان في المقدار ومتعاكستان في الاتجاه", "القوة على الفيل أكبر وبالاتجاه نفسه", "القوة على الرجل أكبر ومتعاكستان في الاتجاه", "متساويتان في المقدار وبالاتجاه نفسه"], 0, 64, "bookimg/elephant.webp"], ["في الشكل، إذا كانت كتلة الفيل 10 أضعاف كتلة الرجل، وتسارع الرجل بمقدار 10 م/ث²، فما مقدار تسارع الفيل؟", ["1 م/ث²", "10 م/ث²", "100 م/ث²", "0.1 م/ث²"], 0, 64, "bookimg/elephant.webp"]], "bq": [["رجل وفيل يقفان على مزلاجتين في حالة سكون، دفع الرجل الفيل بقوة (ق). قارن بين القوة المؤثرة على الرجل والقوة المؤثرة على الفيل من حيث المقدار والاتجاه.", "متساويتان في المقدار ومتعاكستان في الاتجاه (القانون الثالث لنيوتن).", 64], ["إذا كانت كتلة الفيل ١٠ أضعاف كتلة الرجل، فاحسب مقدار تسارع الفيل إذا تسارع الرجل بمقدار ١٠م/ث².", "القوتان متساويتان، والتسارع = ق ÷ ك، فتسارع الفيل = ١٠ ÷ ١٠ = ١ م/ث².", 64]]}]}, {"id": "U4", "part": 1, "t": "الوحدة الرابعة: عناصر الحالة الجوية", "les": [{"t": "الغلاف الجوي", "pg": 69, "pts": ["يحيط بالأرض مجموعة من الغازات تنجذب نحو الأرض بفعل الجاذبية الأرضية لتشكّل غلافًا غازيًّا يعرف بالغلاف الجوي. (ص 69)", "يُعدّ غازا الأكسجين والنيتروجين من المكوّنات الأساسية للغلاف الجوي، إضافة إلى غازات بنسب ضئيلة كبخار الماء وثاني أكسيد الكربون. (ص 70)", "التروبوسفير أقرب الطبقات إلى سطح الأرض، تحتوي على 75% من الهواء، وتتناقص درجة الحرارة فيها بمعدّل 6.5 س° كلّما ارتفعنا 1 كم. (ص 71)", "الستراتوسفير تتميّز بالاستقرار التامّ في جوّها، وتخلو من الظواهر الجوية كالغيوم والضباب والأمطار. (ص 71)", "تُعرّف الرطوبة بأنّها كمية بخار الماء الموجودة في الهواء الجوي، ويمكن قياسها باستخدام جهاز الهيجروميتر. (ص 74)", "يتكاثف بخار الماء إذا كان الهواء مشبعًا (الرطوبة النسبية 100%)، وانخفضت درجة الحرارة، ووُجدت نوى تكاثف. (ص 76)"], "terms": [["الغلاف الجوي", "غلاف غازي يحيط بالأرض تنجذب غازاته نحوها بفعل الجاذبية الأرضية. (ص 69)"], ["الرطوبة", "كمية بخار الماء الموجودة في الهواء الجوي. (ص 74)"], ["الرطوبة النسبية", "كتلة بخار الماء الموجود فعليًّا في حجم معيّن من الهواء ÷ كتلة البخار اللازم لإشباع الحجم نفسه عند درجة الحرارة نفسها. (ص 74)"]], "facts": [["النيتروجين أكثر غازات الهواء.", 1], ["طبقة الأوزون في التروبوسفير.", 0], ["تحدث الغيوم والأمطار في التروبوسفير.", 1]], "ex": [["متر مكعّب من الهواء يحتوي على 18 غم من بخار الماء، وأقصى ما يحمله 24 غم. ما الرطوبة النسبية؟", "(18 ÷ 24) × 100% = 75%. (ص 74)"], ["ما القوة التي تبقي الغازات المكونة للغلاف الجوي محيطة بالأرض ؟ (تمرين من الكتاب، ص 89)", "قوة الجاذبية الارضية"], ["أيّ طبقات الغلاف الجوي الآتية تخلو من الظواهر الجوية؟ (تمرين من الكتاب، ص 89)", "الستراتوسفير"], ["ما سبب حدوث نسيم البحر؟ (تمرين من الكتاب، ص 89)", "لأن درجة حرارة اليابسة ترتفع أسرع من درجة حرارة ماء البحر"]], "id": "U4L1", "img": [69, 70, 71, 72, 73, 74, 75, 76, 77, 78, 79], "bmc": [["ما القوة التي تبقي الغازات المكونة للغلاف الجوي محيطة بالأرض ؟", ["قوة الجاذبية الارضية", "قوة الاحتكاك", "قوة الفعل", "قوة رد الفعل"], 0, 89], ["أيّ طبقات الغلاف الجوي الآتية تخلو من الظواهر الجوية؟", ["الستراتوسفير", "التربوسفير", "الميزوسفير", "الثيرموسفير"], 0, 89], ["ما سبب حدوث نسيم البحر؟", ["لأن درجة حرارة اليابسة ترتفع أسرع من درجة حرارة ماء البحر", "لأن الضغط الجوي فوق سطح اليابسة أعلى منه فوق ماء البحر", "لأن الضغط الجوي فوق سطح اليابسة وفوق ماء البحر متساوٍ", "لأن درجة حرارة ماء البحر واليابسة ترتفع بشكل متساوٍ"], 0, 89], ["أيّ الرياح الآتية تهبُّ في مقدمة رياح الخماسين؟", ["المحلية", "اليومية", "التجارية", "الموسمية"], 0, 89], ["ما كتلة بخار الماء اللازمة لإشباع حجم معين من الهواء، إذا علمت أنّ كتلة بخار الماء الموجودة فعليًا في نفس الحجم تساوي (١٥) غم ورطوبته النسبية ٦٠٪؟", ["٢٥", "١٠", "١٥", "٤٠"], 0, 90]]}, {"t": "الضغط الجوي", "pg": 80, "pts": ["يُعرّف الضغط الجوي بأنّه وزن عمود الهواء الواقع عموديًّا على وحدة المساحة. (ص 80)", "عندما ترتفع درجة الحرارة في منطقة ما يتمدّد الهواء ويرتفع ويقلّ ضغطه، فتهبّ الرياح من منطقة الضغط المرتفع إلى منطقة الضغط المنخفض. (ص 81)", "اخترع تورشيللي البارومتر الزئبقي، وتوقّف الزئبق عند ارتفاع 76 سم، وهي قيمة الضغط الجوي عند مستوى سطح البحر في الظروف المعيارية. (ص 84)", "نهارًا ترتفع حرارة اليابسة أسرع من البحر فيهبّ الهواء من البحر إلى اليابسة (نسيم البحر)، وليلًا يهبّ من اليابسة إلى البحر (نسيم البرّ). (ص 85)", "تُعرّف الرياح بأنّها هواء متحرّك، ويُحدّد اتجاهها بدوّارة الرياح، وتقاس سرعتها بجهاز الأنيمومتر. (ص 86–87)"], "terms": [["الضغط الجوي", "وزن عمود الهواء الواقع عموديًّا على وحدة المساحة. (ص 80)"], ["البارومتر", "جهاز لقياس الضغط الجوي. (ص 84)"], ["الرياح", "هواء متحرّك. (ص 86)"], ["نسيم البحر", "هبوب الهواء الملامس لسطح البحر إلى اليابسة نهارًا. (ص 85)"]], "facts": [["يقلّ الضغط الجوي في قمم الجبال.", 1], ["تهبّ الرياح من الضغط المنخفض إلى المرتفع.", 0]], "ex": [["إذا كانت سرعة الرياح 25 عقدة، فما سرعتها بوحدة كم/س؟", "السرعة = 25 × 1.853 = 46.325 كم/ساعة. (ص 87)"], ["ما مقدار الضغط الجوي عند مستوى سطح البحر في الظروف المعيارية؟ (تمرين من الكتاب، ص 89)", "٧٦٠ مليمتر زئبق"], ["ما الجهاز المستخدم لقياس الضغط الجوي؟ (تمرين من الكتاب، ص 89)", "الباروميتر"], ["في أي المناطق الفلسطينية الآتية تكون قيمة الضغط الجوي هي الأكبر؟ (تمرين من الكتاب، ص 90)", "البحر الميت"]], "id": "U4L2", "img": [80, 81, 82, 83, 84, 85, 86, 87, 88, 89, 90, 91, 92, 93], "bmc": [["ما مقدار الضغط الجوي عند مستوى سطح البحر في الظروف المعيارية؟", ["٧٦٠ مليمتر زئبق", "٧٥ سم زئبق", "٧٠ سم زئبق", "٦٧٠ مليمتر زئبق"], 0, 89], ["ما الجهاز المستخدم لقياس الضغط الجوي؟", ["الباروميتر", "الهيجروميتر", "الثيرموميتر", "الأنيموميتر"], 0, 89], ["في أي المناطق الفلسطينية الآتية تكون قيمة الضغط الجوي هي الأكبر؟", ["البحر الميت", "رام الله", "حيفا", "جبل جرزيم"], 0, 90]]}]}, {"id": "U5", "part": 1, "t": "الوحدة الخامسة: الضغط والموائع — الجزء الثاني", "les": [{"t": "الكثافة", "pg": 1004, "p2": 1, "pts": ["تُعرَّف المادة بأنها كل شيء له كتلة ويشغل حيّزًا. عندما تتساوى المواد المختلفة في حجومها فإنها تختلف في كتلها، وبالتالي نميّز مادة من أخرى باختلاف النسبة بين الكتلة إلى الحجم في المادتين التي تُعرف بالكثافة. (ص 5)", "الكثافة هي كتلة وحدة الحجوم من المادة، وتُحسب من خلال كتلة جسم ما إلى حجمه، وهي ثابتة للمادة الواحدة عند درجة حرارة معيّنة، وتختلف من مادة لأخرى. (ص 5)", "يمكن قياس الكثافة بوحدة كغم/م³ أو غم/سم³، ويُعبَّر عن علاقة الكثافة بالكتلة والحجم رياضيًّا: الكثافة = الكتلة ÷ الحجم. (ص 5)", "تُعدّ الكثافة من الخصائص التي تميّز المواد من بعضها بعضًا، فعند درجة حرارة معيّنة إذا اختلط سائلان لا يذوب أحدهما في الآخر فإن السائل الأقل كثافة يستقرّ في الأعلى. (ص 7)", "لحساب حجم جسم غير منتظم الشكل: نضعه في مخبار مدرّج فيه ماء، وحجمه = الفرق بين قراءتي التدريج. (ص 7–8)"], "terms": [["المادة", "كل شيء له كتلة ويشغل حيّزًا. (ص 5)"], ["الكثافة", "كتلة وحدة الحجوم من المادة = الكتلة ÷ الحجم. (ص 5)"]], "ex": [["احسب كثافة عينة من مادة ما كتلتها 178 غم وحجمها 20 سم³. (ص 6)", "الكثافة = الكتلة ÷ الحجم = 178 ÷ 20 = 8,9 غم/سم³"], ["قطعة معدنية غير منتظمة كتلتها 77 غم، وُضعت في مخبار فيه 50 مل ماء فأصبحت القراءة 60 مل. جد كثافتها. (ص 8)", "الحجم = 60 − 50 = 10 سم³، الكثافة = 77 ÷ 10 = 7,7 غم/سم³"], ["سبيكة ذهبية كتلتها 57 غم وكثافتها 19 غم/سم³ فما حجمها؟ (ص 9)", "الحجم = الكتلة ÷ الكثافة = 57 ÷ 19 = 3 سم³"], ["ما نوع مادة العينة التي كثافتها 8,9 غم/سم³ مستعينًا بجدول الكثافات (النحاس 8,92، الحديد 7,86، الذهب 19,3)؟ (ص 6، سؤال 1) (تمرين من الكتاب، ص 6)", "النحاس"]], "id": "U5L1", "img": [1004, 1005, 1006, 1007, 1008, 1009], "bmc": [["ما نوع مادة العينة التي كثافتها 8,9 غم/سم³ مستعينًا بجدول الكثافات (النحاس 8,92، الحديد 7,86، الذهب 19,3)؟ (ص 6، سؤال 1)", ["النحاس", "الحديد", "الذهب"], 0, 6], ["إذا اختلط الماء والعسل والزيت في كأس، فأيّ السوائل يستقرّ في الأعلى؟ (ص 6–7، نشاط 3)", ["الزيت لأنه الأقل كثافة", "العسل لأنه الأكثر كثافة", "الماء"], 0, 7], ["سبيكة ذهبية من النوع نفسه حجمها 9 سم³ (كثافة 19 غم/سم³). ما كتلتها؟ (ص 9، سؤال 1)", ["171 غم", "57 غم", "28 غم"], 0, 9], ["ما كتلة الهواء داخل غرفة قياسها 6م × 5م × 4م إذا علمت أن كثافة الهواء 1,3 كغم/م³؟ (ص 9، سؤال 2)", ["156 كغم", "120 كغم", "92,3 كغم"], 0, 9]]}, {"t": "الضغط", "pg": 1010, "p2": 1, "pts": ["يُطلق على النسبة بين القوة العمودية المؤثرة على سطح ما ومساحة ذلك السطح الضغط. (ص 12)", "يزداد الضغط بزيادة القوة المؤثرة على سطح معيّن وينقص بنقصانها، بينما يقلّ الضغط بزيادة مساحة السطح الذي تؤثر فيه قوة عمودية معيّنة، ويزداد بنقصان المساحة. (ص 12)", "الضغط = القوة العمودية المؤثرة ÷ مساحة السطح (ض = ق ÷ م). (ص 12)", "وحدات القياس: القوة بالنيوتن (كغم.م/ث²)، والمساحة بالمتر المربع (م²)، والضغط بالنيوتن/م² = باسكال. (ص 12)"], "terms": [["الضغط", "النسبة بين القوة العمودية المؤثرة على سطح ما ومساحة ذلك السطح. (ص 12)"], ["الباسكال", "وحدة قياس الضغط = نيوتن/م². (ص 12)"]], "ex": [["أثّر جسم بقوة مقدارها 200 نيوتن في سطح أفقي مساحته 0,01 م². احسب مقدار الضغط الواقع على ذلك السطح. (ص 14)", "ض = ق ÷ م = 200 ÷ 0,01 = 20000 باسكال"], ["فكّر: إذا وُضع بالون على دبوس واحد وضُغط عليه فإنه ينفجر، وإذا وُضع على عدد كبير من الدبابيس لا ينفجر. (ص 12)", "لأن زيادة مساحة السطح تقلّل الضغط الواقع على البالون."], ["ما العلاقة بين مدى انغراس قدمك بالرمل ومقدار الضغط الذي تؤثر فيه على الرمل؟ (ص 13، نشاط 3)", "عند الوقوف على قدم واحدة تقلّ المساحة فيزداد الضغط ويزداد الانغراس."], ["قطعة نحاس مكعبة حجمها 0,008 م³ وكثافتها 8600 كغم/م³. ما كتلتها؟ (ص 14، سؤال) (تمرين من الكتاب، ص 14)", "68,8 كغم"]], "id": "U5L2", "img": [1010, 1011, 1012, 1013, 1014], "bmc": [["قطعة نحاس مكعبة حجمها 0,008 م³ وكثافتها 8600 كغم/م³. ما كتلتها؟ (ص 14، سؤال)", ["68,8 كغم", "8600 كغم", "1075 كغم"], 0, 14], ["قطعة نحاس كتلتها 68,8 كغم، وتسارع الجاذبية 10 م/ث². ما وزنها؟ (ص 14، سؤال)", ["688 نيوتن", "68,8 نيوتن", "6,88 نيوتن"], 0, 14], ["ماذا يحدث للضغط عند زيادة مساحة السطح الذي تؤثر فيه قوة عمودية معيّنة؟ (ص 12)", ["يقلّ", "يزداد", "لا يتغيّر"], 0, 12], ["إذا كان الضغط عند وقوفك على قدميك 5,4 × 10⁵ باسكال، كم يصبح إذا وقفت على قدم واحدة؟ (ص 28، س1 فقرة 1)", ["10,8 × 10⁵ باسكال", "2,7 × 10⁵ باسكال", "5,4 × 10⁵ باسكال", "21,6 × 10⁵ باسكال"], 0, 28], ["يجلس فتى وزنه 400 نيوتن على كرسي وزنه 40 نيوتن له أربعة أرجل مساحة كل منها 0,002 م². ما الضغط على الأرض؟ (ص 29، السؤال الرابع)", ["55000 باسكال", "50000 باسكال", "220000 باسكال"], 0, 29]]}, {"t": "الضغط في السوائل", "pg": 1015, "p2": 1, "pts": ["تتكوّن المادة من دقائق صغيرة وتوجد في حالات ثلاث: الصلبة والسائلة والغازية. في حالة الصلابة تتحرك دقائق المادة حركة موضعية اهتزازية وتمتاز بثبات الحجم والشكل؛ لأن قوى التماسك بين دقائقها كبيرة. (ص 16)", "في حالة السيولة تحتفظ المادة بحجمها وتأخذ شكل الإناء الذي توضع فيه بسبب ضعف قوى التماسك، وفي الحالة الغازية تكاد تكون قوى التماسك معدومة فلا تحتفظ المادة بشكل ثابت ولا بحجم ثابت، ويُطلق على السوائل والغازات اسم الموائع. (ص 16)", "يؤثر وزن الماء بقوة على قاعدة الإناء الموضوع فيه مسبّبًا ضغطًا على قاعدته: ضغط السائل = الارتفاع × الكثافة × ج (ض = ل × ث × ج). (ص 17–18)", "مبدأ باسكال: «إذا وقع ضغط خارجي على سائل محصور فإن هذا الضغط ينتقل إلى جميع أجزاء السائل وفي جميع الاتجاهات بالتساوي». (ص 20)", "من تطبيقات مبدأ باسكال المكبس الهيدروليكي ونظام الكوابح في السيارات. ق١ ÷ م١ = ق٢ ÷ م٢، وتُسمّى النسبة بين مساحة الأسطوانة الكبرى إلى مساحة الأسطوانة الصغرى الفائدة الآلية للمكبس الهيدروليكي. (ص 21)"], "terms": [["الموائع", "السوائل والغازات. (ص 16)"], ["مبدأ باسكال", "الضغط الخارجي على سائل محصور ينتقل إلى جميع أجزائه وفي جميع الاتجاهات بالتساوي. (ص 20)"], ["الفائدة الآلية", "النسبة بين مساحة الأسطوانة الكبرى إلى مساحة الأسطوانة الصغرى في المكبس الهيدروليكي. (ص 21)"]], "ex": [["عمق الماء خلف سدّ 20 مترًا، فما ضغط الماء عند قاعدة السد؟ (ص 18)", "الضغط = 20 × 1000 × 10 = 200000 باسكال"], ["وما ضغط الماء عند نقطة تقع على عمق 5 أمتار من سطح الماء؟ (ص 18)", "الضغط = 5 × 1000 × 10 = 50000 باسكال"], ["مكبس هيدروليكي مساحة أسطوانته الكبرى 0,2 م² والصغرى 0,05 م². جد الفائدة الآلية. (ص 21)", "الفائدة الآلية = 0,2 ÷ 0,05 = 4"], ["وقف رجل كتلته 100 كغم على الأسطوانة الكبرى (0,2 م²)، فما وزن الابن اللازم على الصغرى (0,05 م²) لرفعه؟ (ص 22)", "وزن الأب = 100 × 10 = 1000 نيوتن، وزن الابن = 1000 × 0,05 ÷ 0,2 = 250 نيوتن"]], "id": "U5L3", "img": [1015, 1016, 1017, 1018, 1019, 1020, 1021, 1022], "bmc": [["إذا كان ضغط الماء على عمق ل يساوي 400000 باسكال فما مقدار ل؟ (ص 28، س1 فقرة 2)", ["40 م", "10 م", "20 م", "80 م"], 0, 28], ["مكبس هيدروليكي مساحة أسطوانته الصغرى 0,02 م² والكبرى 0,4 م²، أثّرت قوة 80 نيوتن في الصغرى. ما القوة في الكبرى؟ (ص 28، س1 فقرة 3)", ["1600 نيوتن", "80 نيوتن", "160 نيوتن", "800 نيوتن"], 0, 28], ["ما القوة التي يؤثر بها الماء على قاعدة خزان مربعة طول ضلعها 4 م وارتفاع الماء فوقها 2 م؟ (ص 28، س1 فقرة 4)", ["32 × 10⁴ نيوتن", "8 × 10⁴ نيوتن", "16 × 10⁴ نيوتن", "192 × 10⁴ نيوتن"], 0, 28], ["في أيّ اتجاه يؤثر الضغط عند نقطة داخل سائل؟ (ص 28، س1 فقرة 8)", ["في جميع الاتجاهات", "إلى الأسفل فقط", "إلى الأعلى فقط", "إلى جوانب الإناء فقط"], 0, 28], ["كرسي طبيب أسنان وزنه 1600 نيوتن يرتكز على أسطوانة مساحتها 0,144 م². ما القوة اللازمة على أسطوانة مساحتها 0,0072 م²؟ (ص 29، السؤال الثالث)", ["80 نيوتن", "160 نيوتن", "32000 نيوتن"], 0, 29]]}, {"t": "قاعدة أرخميدس", "pg": 1023, "p2": 1, "pts": ["يغوص الجسم في الماء عندما تكون كثافته أكبر من كثافة الماء، ويطفو على سطح الماء عندما تكون كثافته أقل من كثافة الماء، ويبقى معلّقًا في الماء عند تساوي كثافته مع كثافة الماء. (ص 24)", "توصّل العالم أرخميدس إلى أن قوة الطفو تنشأ من غمر جسم ما في مائع كليًّا أو جزئيًّا؛ حيث يتساوى وزن المائع المزاح أثناء الغمر مع الخسارة الظاهرية في الوزن. (ص 26)", "قاعدة أرخميدس: «يتعرّض الجسم المغمور كليًّا أو جزئيًّا في مائع ما لقوة تدفعه رأسيًّا إلى أعلى تُسمّى قوة الطفو ومقدارها يساوي وزن المائع المزاح». (ص 26)", "عند غمر جسم كليًّا في سائل: حجم الجسم = حجم السائل المزاح، ووزن السائل المزاح = الخسارة الظاهرية في وزن الجسم = وزنه في الهواء – وزنه في السائل، وقوة الطفو = وزن السائل المزاح. (ص 26)"], "terms": [["قوة الطفو", "قوة تدفع الجسم المغمور في مائع رأسيًّا إلى أعلى، مقدارها يساوي وزن المائع المزاح. (ص 26)"], ["الخسارة الظاهرية في الوزن", "وزن الجسم في الهواء – وزنه في السائل. (ص 26)"]], "ex": [["جسم وزنه في الهواء 8 نيوتن وحجمه 200 سم³ غُمر في الماء فأصبح وزنه 6 نيوتن. احسب وزن الماء المزاح. (ص 27)", "وزن الماء المزاح = 8 – 6 = 2 نيوتن"], ["احسب حجم الماء المزاح في المثال السابق. (ص 27)", "حجم الماء المزاح = حجم الجسم = 200 سم³"], ["فكّر: الطفو في مياه البحر الميت أسهل منه في مياه البحر المتوسط. (ص 24)", "لأن كثافة مياه البحر الميت أكبر."], ["جسم وزنه في الهواء 8 نيوتن ووزنه في الماء صفر. فما وزن السائل المزاح؟ (ص 28، س1 فقرة 6) (تمرين من الكتاب، ص 28)", "8 نيوتن"]], "id": "U5L4", "img": [1023, 1024, 1025, 1026, 1027, 1028, 1029, 1030, 1031], "bmc": [["جسم وزنه في الهواء 8 نيوتن ووزنه في الماء صفر. فما وزن السائل المزاح؟ (ص 28، س1 فقرة 6)", ["8 نيوتن", "صفر", "4 نيوتن", "16 نيوتن"], 0, 28], ["كرة وزنها في الهواء 9 نيوتن غُمرت في سائل فأصبح وزنها 6 نيوتن. فما وزن السائل المزاح بالنيوتن؟ (ص 28، س1 فقرة 7)", ["3", "9", "6", "4"], 0, 28], ["متى يطفو الجسم على سطح الماء؟ (ص 24)", ["عندما تكون كثافته أقل من كثافة الماء", "عندما تكون كثافته أكبر من كثافة الماء", "عندما تتساوى كثافته مع كثافة الماء"], 0, 24], ["غُمر جسم حجمه 0,0005 م³ كليًّا في الماء. ما حجم الماء المزاح؟ (ص 27، سؤال)", ["0,0005 م³", "0,005 م³", "5 م³"], 0, 27], ["جسم من القرميد كتلته 360 كغم وكثافته 1800 كغم/م³ غُمر في الماء. ما وزن الماء المزاح؟ (ص 29، السؤال الثاني)", ["2000 نيوتن", "3600 نيوتن", "200 نيوتن"], 0, 29]]}]}, {"id": "U6", "part": 1, "t": "الوحدة السادسة: المحاليل في حياتنا — الجزء الثاني", "les": [{"t": "المحاليل", "pg": 1032, "p2": 1, "pts": ["يُعدّ الماء مذيبًا عامًّا لكثير من المواد كالسكر والملح والكحول وبعض الغازات، مكوّنًا محاليل مائية. (ص 33)", "يتكوّن المحلول من مذيب ومذاب، وتُسمّى المادة الأقل في كميتها مذابًا، والمادة الأخرى التي كميتها أكثر مذيبًا، والخليط الناتج عنهما محلولًا. يُعدّ الماء مذيبًا حتى لو كانت كميته أقل. (ص 33)", "تُصنّف المحاليل المائية من حيث حالة المذاب والمذيب إلى: محلول صلب في سائل (السكر في الماء)، ومحلول سائل في سائل (الكحول في الماء)، ومحلول غاز في سائل (غاز الأكسجين في الماء). (ص 33)", "يحدث التبخر من سطح الماء في جميع درجات الحرارة، وعندما يكون الماء غير نقي فإنه يتبخر وتبقى المادة المذابة على شكل مادة صلبة. ومن طرق فصل المذاب عن المذيب أيضًا: التقطير، والترشيح، والترسيب والترويق. (ص 34–35)", "المحلول الحقيقي: تتوزع دقائق المذاب تمامًا ويكون متجانسًا. المحلول المعلّق: تترسب دقائق المذاب بعد فترة قصيرة لكبر حجمها ويكون غير متجانس. المحلول الغروي: تبقى دقائق المذاب عالقة في المحلول. (ص 36)", "العوامل المؤثرة في سرعة الذوبان: حجم بلورات المذاب (كلما كان أصغر زادت سرعة الذوبان)، ودرجة الحرارة (كلما زادت درجة حرارة المذيب زادت سرعة الذوبان في معظم المواد)، والتحريك. (ص 37–39)"], "terms": [["المذاب", "المادة الأقل في كميتها في المحلول. (ص 33)"], ["المذيب", "المادة التي كميتها أكثر في المحلول (والماء يُعدّ مذيبًا حتى لو كانت كميته أقل). (ص 33)"], ["المحلول الحقيقي", "محلول متجانس تتوزع فيه دقائق المذاب تمامًا. (ص 36)"], ["المحلول المعلّق", "محلول غير متجانس تترسب دقائق المذاب فيه لكبر حجمها. (ص 36)"], ["المحلول الغروي", "محلول تبقى دقائق المذاب عالقة فيه. (ص 36)"]], "ex": [["في أيّ الكأسين تذوب بلورات السكر أسرع: السكر الناعم أم الخشن؟ (ص 37، نشاط 6)", "السكر الناعم؛ لأنه كلما كان حجم البلورات أصغر تخللت الفراغات بين جزيئات المذيب بشكل أسرع."], ["في أيّ الكأسين يكون ذوبان الملح أسرع: الماء البارد أم الماء المسخّن إلى 50 °س؟ (ص 38، نشاط 7)", "في الماء المسخّن؛ فكلما زادت درجة حرارة المذيب زادت سرعة الذوبان."], ["فكّر: تتنفس الأسماك في الماء. (ص 33)", "لأن غاز الأكسجين يذوب في الماء (محلول غاز في سائل)."], ["أيّ المواد الآتية يُعدّ مذيبًا عامًّا؟ (ص 48، س1 فقرة 1) (تمرين من الكتاب، ص 48)", "الماء"]], "id": "U6L1", "img": [1032, 1033, 1034, 1035, 1036, 1037, 1038, 1039], "bmc": [["أيّ المواد الآتية يُعدّ مذيبًا عامًّا؟ (ص 48، س1 فقرة 1)", ["الماء", "البنزين", "الكحول", "الزيت"], 0, 48], ["أيّ المحاليل الآتية يُعدّ محلولًا غرويًّا؟ (ص 48، س1 فقرة 2)", ["الحليب", "الزهورات", "الشاي", "العطر"], 0, 48], ["ما تصنيف محلول ثاني أكسيد الكربون في المشروبات الغازية؟ (ص 48، س1 فقرة 3)", ["غاز/سائل", "سائل/صلب", "سائل/سائل", "غاز/غاز"], 0, 48], ["ما الطريقة المناسبة لفصل مكونات محلول سكري؟ (ص 48، س1 فقرة 8)", ["التبخير", "الترشيح", "الترويق", "الترسيب"], 0, 48], ["عند تسخين محلول ملح الطعام والماء، ماذا يحدث؟ (ص 49، السؤال الثالث)", ["يتبخر الماء ويبقى الملح في الوعاء", "يتبخر المحلول كليًّا", "يتبخر الملح ويبقى الماء"], 0, 49]]}, {"t": "تركيز المحاليل", "pg": 1040, "p2": 1, "pts": ["يُعبَّر عن التركيز بأنه النسبة بين كتلة المادة المذابة إلى حجم معيّن من المحلول: التركيز = كتلة المذاب (غرام) ÷ حجم المحلول (لتر)، ومن وحدات قياسه غم/لتر. (ص 41)", "المحلول الوريدي يُحضَّر بتركيز 0,9% بالكتلة: 9 غم من الملح مع ماء مقطر لتصبح كتلة المحلول 1000 غم. (ص 42)", "تُعرف عملية التخليل بأنها عملية وضع المادة الغذائية في محلول ملحي بتركيز معيّن، ومن أمثلتها تخليل الخيار والفقوس والجزر والفلفل الحار والزيتون. (ص 44)", "تُحفظ المخللات في محاليل ملحية بتركيز (1:8) للمحافظة على قوام المخللات، وعدم توفير بيئة مناسبة لنمو خمائر العفن، ويُضاف السكر لتسريع عملية التخليل. (ص 44)"], "terms": [["التركيز", "النسبة بين كتلة المادة المذابة إلى حجم معيّن من المحلول (غم/لتر). (ص 41)"], ["التخليل", "وضع المادة الغذائية في محلول ملحي بتركيز معيّن. (ص 44)"]], "ex": [["احسب تركيز محلول ناتج عن إذابة 4 غم من ملح كربونات الصوديوم في نصف لتر من المحلول. (ص 41)", "التركيز = 4 ÷ 0,5 = 8 غم/لتر"], ["احسب تركيز المحلول الناتج عن إذابة 20 غم كلوريد صوديوم في لترين ماء. (ص 41، سؤال)", "التركيز = 20 ÷ 2 = 10 غم/لتر"], ["أُذيب 300 غ من غلايكول إثيلين في لترين من الماء المقطر. احسب تركيز المحلول. (ص 49، السؤال الثاني)", "التركيز = 300 ÷ 2 = 150 غم/لتر"], ["ما تركيز المحلول الناتج من إذابة 5 غم سكر في نصف لتر من المحلول؟ (ص 48، س1 فقرة 4) (تمرين من الكتاب، ص 48)", "10 غم/لتر"]], "id": "U6L2", "img": [1040, 1041, 1042, 1043, 1044], "bmc": [["ما تركيز المحلول الناتج من إذابة 5 غم سكر في نصف لتر من المحلول؟ (ص 48، س1 فقرة 4)", ["10 غم/لتر", "5 غم/لتر", "2 غم/لتر", "15 غم/لتر"], 0, 48], ["ما وظيفة محلول ملح كلوريد الصوديوم الذي يُستعمل لتخليل الفقوس؟ (ص 48، س1 فقرة 7)", ["لحفظه متماسكًا فترة من الزمن", "المحافظة على طعمه", "جعله طريًّا", "المحافظة على لونه"], 0, 48], ["لماذا يُضاف السكر في عملية التخليل؟ (ص 44)", ["لتسريع عملية التخليل", "لمنع نمو العفن", "لتغيير اللون"], 0, 44], ["كم غرامًا من الملح تُوزن لتحضير المحلول الوريدي (0,9%) بكتلة محلول 1000 غم؟ (ص 42، نشاط 3)", ["9 غم", "0,9 غم", "90 غم"], 0, 42]]}, {"t": "الذائبية", "pg": 1045, "p2": 1, "pts": ["تتفاوت المواد في درجة ذوبانها في نفس الكمية من الماء وعلى نفس درجة الحرارة؛ فمثلًا تكون كمية سكر المائدة الذائبة أكبر من كمية ملح الطعام المذابة عند نفس الظروف. (ص 46)", "لكل مذيب قدرة محدّدة على إذابة كمية من المذاب على درجة حرارة معيّنة، وتُسمّى أكبر كتلة من المذاب التي تذوب في 100 غم ماء عند درجة حرارة معيّنة بالذائبية، ويُسمّى المحلول عندها بالمحلول المشبع. (ص 46)", "في حال زيادة كمية المادة المذابة عن حدّ الإشباع برفع درجة حرارة المحلول ثم تبريده تدريجيًّا دون تحريك يُسمّى المحلول بالمحلول فوق المشبع. (ص 46)", "الذائبية = كتلة المذاب (غم) × 100 ÷ كتلة الماء (غم)، وتُقاس بوحدة غم/100 غم ماء. (ص 47)"], "terms": [["الذائبية", "أكبر كتلة من المذاب تذوب في 100 غم ماء عند درجة حرارة معيّنة. (ص 46)"], ["المحلول المشبع", "المحلول الذي أُذيبت فيه أكبر كمية من المذاب عند درجة حرارة معيّنة. (ص 46)"], ["المحلول فوق المشبع", "محلول زادت فيه كمية المذاب عن حدّ الإشباع برفع درجة الحرارة ثم التبريد التدريجي دون تحريك. (ص 46)"]], "ex": [["حُضّر محلول مشبع من نترات الفضة بإذابة 5,5 غم في 25 غم ماء عند 25 °س. احسب الذائبية. (ص 47)", "الذائبية = 5,5 × 100 ÷ 25 = 22 غم/100 غم ماء"], ["ذائبية كلوريد البوتاسيوم 35 غم/100 غم عند 30 °س. احسب كتلة الملح اللازمة لتحضير محلول مشبع في 500 غم ماء. (ص 47، سؤال)", "الكتلة = 35 × 500 ÷ 100 = 175 غم"], ["ما المصطلح العلمي الذي يُطلق على أكبر كتلة من المذاب يمكن أن تذوب في 100 غم ماء عند درجة معيّنة؟ (ص 48، س1 فقرة 5) (تمرين من الكتاب، ص 48)", "الذائبية"], ["احسب كتلة ملح الطعام اللازم إذابتها في 50 غم ماء لتحضير محلول مشبع ذائبيته 10 غم/100 غم ماء. (ص 48، س1 فقرة 6) (تمرين من الكتاب، ص 48)", "5 غم"]], "id": "U6L3", "img": [1045, 1046, 1047, 1048, 1049, 1050, 1051, 1052], "bmc": [["ما المصطلح العلمي الذي يُطلق على أكبر كتلة من المذاب يمكن أن تذوب في 100 غم ماء عند درجة معيّنة؟ (ص 48، س1 فقرة 5)", ["الذائبية", "التركيز", "المحلول", "المذيب"], 0, 48], ["احسب كتلة ملح الطعام اللازم إذابتها في 50 غم ماء لتحضير محلول مشبع ذائبيته 10 غم/100 غم ماء. (ص 48، س1 فقرة 6)", ["5 غم", "10 غم", "20 غم", "15 غم"], 0, 48], ["عند إذابة 10 غم سكر في 50 غم ماء (ذائبية السكر 30 غم/100 غم ماء عند 25 °س)، أيّ العبارات صحيحة؟ (ص 49، س1 فقرة 10)", ["تذوب جزيئات السكر بين جزيئات الماء كليًّا", "يشتّت المحلول الناتج الضوء", "يترسّب 5 غم من السكر في قاع المحلول", "يُعدّ المحلول مثالًا لمحلول سائل في سائل"], 0, 49], ["ماذا يُسمّى المحلول لحظة بدء ترسب بلورات المذاب فيه؟ (ص 46، نشاط 2)", ["المحلول المشبع", "المحلول فوق المشبع", "المحلول المخفّف"], 0, 46]]}]}, {"id": "U7", "part": 1, "t": "الوحدة السابعة: أجهزة جسم الإنسان — الجزء الثاني", "les": [{"t": "الجهاز العصبي", "pg": 1053, "p2": 1, "pts": ["تمثّل الاستجابة ردّ فعل لمثير ما، تكون إما تغيّرات جسمية مثل الانفعال عند رؤية كائن مخيف، أو سلوكًا بسيطًا كالحركة. ويُعدّ الجهاز العصبي أحد أجهزة جسم الإنسان الذي يحتوي على مجموعة من الخلايا العصبية التي تساهم في تأثّر الجسم بالظروف البيئية الخارجية والداخلية. (ص 53)", "تمثّل الخلايا العصبية (العصبونات) وحدة البناء والوظيفة في الجهاز العصبي، فمنها الحسية التي تنقل المؤثرات من عضو الاستقبال إلى الجهاز العصبي المركزي، والحركية التي تنقل أوامره إلى عضو الاستجابة (غدة أو عضلة)، والموصلة التي تصل بين الحسية والحركية. وتتكوّن الخلية العصبية من: زوائد شجرية، وجسم الخلية الذي يحتوي على نواة، ومحور أسطواني طويل. (ص 53–54)", "يتكوّن الجهاز العصبي من جهاز عصبي مركزي (الدماغ والحبل الشوكي) وجهاز عصبي طرفي (الأعصاب الصادرة والواردة). (ص 54)", "يقع الدماغ داخل تجويف الجمجمة، وحماه الله بوسائل مرتبة من الخارج إلى الداخل: الشعر، والجلد، والجمجمة، وأغشية السحايا، والسائل المخي. (ص 55)", "يُعدّ المخ أكبر أجزاء الدماغ، ويتكوّن من نصفين متماثلين يتصلان بالجسم الجاسئ، وعلى سطحه انثناءات تُسمّى التلافيف. من وظائفه: استقبال المعلومات الحسية وإدراكها، وتنظيم حركة العضلات الإرادية، والقيام بالعمليات العقلية كالتذكّر والفهم والتفكير والابتكار. (ص 56)", "يُعدّ المخيخ ثاني أكبر أجزاء الدماغ، ويقع أسفل المخ، ويعمل على معالجة المعلومات الحسية والتنسيق بينها للمحافظة على توازن الجسم. أما جذع الدماغ (النخاع المستطيل والدماغ المتوسط والقنطرة) فينقل المعلومات بين الدماغ وأعضاء الجسم ويسيطر على كثير من الأفعال اللاإرادية كنبض القلب وحركات التنفس. (ص 57–58)", "يتصل الحبل الشوكي بالنخاع المستطيل ويمتد داخل قناة العمود الفقري، وينقل المعلومات الحسية إلى الدماغ وأوامره إلى أعضاء الاستجابة، وتصدر عنه أحيانًا أوامر سريعة دون الرجوع إلى الدماغ وهو ما يُسمّى الفعل المنعكس. (ص 59)", "يتكوّن الجهاز العصبي الطرفي من أعصاب دماغية (12 زوجًا) وأعصاب شوكية (31 زوجًا)، وأليافها حسية وحركية. (ص 61)"], "terms": [["العصبون", "الخلية العصبية، وحدة البناء والوظيفة في الجهاز العصبي. (ص 53)"], ["التلافيف", "انثناءات عديدة على الجزء الخارجي من المخ. (ص 56)"], ["الجسم الجاسئ", "جسر من الألياف العصبية يصل نصفي المخ. (ص 56)"], ["الفعل المنعكس", "أوامر يصدرها الحبل الشوكي إلى العضلات كردّ فعل سريع دون الرجوع إلى الدماغ. (ص 59)"]], "ex": [["لماذا يكتب بعض الأشخاص باليد اليسرى؟ (ص 56، نشاط 5)", "الجزء الأيسر من المخ يتحكم باليد اليمنى للكتابة، بعكس الجزء الأيمن الذي يتحكم باليد اليسرى."], ["ما سبب فقدان الشخص توازنه أحيانًا عند رمي الجلّة؟ وأيّ أجزاء الدماغ مسؤول عن ذلك؟ (ص 57، نشاط 6)", "المخيخ، فهو ينسّق المعلومات الحسية للمحافظة على توازن الجسم."], ["ماذا يحدث عند التعرّض لوخزة دبوس؟ (ص 59)", "يصدر الحبل الشوكي أمرًا سريعًا للعضلات دون الرجوع إلى الدماغ (فعل منعكس)."], ["اذكر طرق المحافظة على صحة الجهاز العصبي. (ص 60)", "تناول الغذاء الصحي، واتخاذ التدابير التي تقي من الإصابات، والنوم والراحة الكافيان، والابتعاد عن ملوثات البيئة."]], "id": "U7L1", "img": [1053, 1054, 1055, 1056, 1057, 1058, 1059, 1060, 1061], "bmc": [["ما اسم الوحدة البنائية للجهاز العصبي؟ (ص 78، س1 فقرة 1)", ["خلية عصبية", "خلية عضلية", "خلية ضامة", "خلية طلائية"], 0, 78], ["قفز أحمد فجأة عند رؤيته أفعى، فأيّ أجزاء الجهاز العصبي يُعدّ مسؤولًا عن هذه الاستجابة؟ (ص 78، س1 فقرة 8)", ["الحبل الشوكي", "المخ", "المخيخ", "جذع الدماغ"], 0, 78], ["أيّ أجزاء الدماغ يقوم بالعمليات العقلية من تذكّر وتفكير؟ (ص 79، السؤال الثاني)", ["المخ", "المخيخ", "النخاع المستطيل"], 0, 79], ["ما عدد أزواج الأعصاب الشوكية؟ (ص 61)", ["31 زوجًا", "12 زوجًا", "10 أزواج"], 0, 61], ["أيّ العصبونات ينقل أوامر الجهاز العصبي المركزي إلى أعضاء الاستجابة؟ (ص 79، السؤال الثاني)", ["العصبون الحركي", "العصبون الحسي", "العصبون الموصل"], 0, 79]]}, {"t": "جهاز الغدد الصماء", "pg": 1062, "p2": 1, "pts": ["تُعرف الغدة بأنها مجموعة من الخلايا التي تفرز مواد لكل منها وظيفة حيوية معيّنة، منها غدد تصبّ إفرازاتها في قنوات خاصة (الغدد القنوية)، ومنها غدد تصبّ إفرازاتها في الدم مباشرة تُعرف بالغدد الصماء التي تتآزر في عملها مع الجهاز العصبي. (ص 62)", "الغدة النخامية غدة صغيرة تقع في قاعدة الدماغ، لا تتجاوز كتلتها نصف غرام، وتسيطر على عمل جميع الغدد الصماء. من هرموناتها: هرمون النمو (زيادة إفرازه تسبب العملقة)، والبرولاكتين المنشّط لإفراز الحليب، والأكسيتوسين المنشّط لإدرار الحليب. (ص 63)", "الغدة الدرقية من أكبر الغدد الصماء، تقع في الناحية الأمامية للرقبة وتشبه الفراشة. من هرموناتها: الثيروكسين الذي ينظّم أكسدة الغذاء وإطلاق الطاقة على شكل حرارة وتنظيم النمو، والكالسيتونين الذي يلعب دورًا في توازن الكالسيوم في الدم. (ص 64)", "يقع البنكرياس خلف المعدة، ويحتوي على جزر لانغرهانز التي تفرز هرموني الأنسولين والغلوكاغون اللذين يعملان على ثبات تركيز السكر في الدم حول معدله الطبيعي (80–100 ملغم/ديسيلتر)؛ فالأنسولين يُنقص تركيز السكر، والغلوكاغون يزيده بتحويل الغلايكوجين إلى سكر. (ص 65)", "تقع الغدتان الكظريتان كل غدة فوق كلية، وعند تعرّض الجسم لموقف طارئ تفرز هرمون الأدرينالين الذي يزيد من عدد ضربات القلب وحركات التنفس واحمرار الوجه. (ص 66)"], "terms": [["الغدة", "مجموعة من الخلايا تفرز مواد لكل منها وظيفة حيوية معيّنة. (ص 62)"], ["الغدد الصماء", "غدد تصبّ إفرازاتها في الدم مباشرة. (ص 62)"], ["الغدد القنوية", "غدد تصبّ إفرازاتها في قنوات خاصة. (ص 62)"], ["الأنسولين", "هرمون من البنكرياس يُنقص تركيز السكر في الدم. (ص 65)"], ["الأدرينالين", "هرمون تفرزه الغدة الكظرية في المواقف الطارئة. (ص 66)"]], "ex": [["إياد يعاني من فقدان الوزن وارتفاع الحرارة وجحوظ العينين وتعرّق زائد. أيّ غدة مصابة؟ (ص 64، نشاط 3)", "فرط في إفراز أحد هرمونات الغدة الدرقية."], ["ماذا يحدث لتركيز السكر في الدم بعد تناول وجبة غذائية؟ (ص 65)", "يزداد، فتُحفَّز جزر لانغرهانز على إفراز الأنسولين الذي يُنقصه ويخزّنه غلايكوجين في الكبد والعضلات."], ["أيّ الغدد أثّر عليها الدماغ عند خوف الأطفال في المخيّم الكشفي، وما الهرمون؟ (ص 66، نشاط 5)", "الغدة الكظرية، وهرمون الأدرينالين."], ["أيّ الغدد الآتية تفرز هرمون الأدرينالين؟ (ص 78، س1 فقرة 4) (تمرين من الكتاب، ص 78)", "الكظرية"]], "id": "U7L2", "img": [1062, 1063, 1064, 1065, 1066], "bmc": [["أيّ الغدد الآتية تفرز هرمون الأدرينالين؟ (ص 78، س1 فقرة 4)", ["الكظرية", "النخامية", "الدرقية", "البنكرياس"], 0, 78], ["أيّ الغدد الآتية يختلف عن الغدد الأخرى؟ (ص 78، س1 فقرة 9)", ["الكظرية", "العرقية", "الدمعية", "اللعابية"], 0, 78], ["أيّ هرمون ينشّط عملية أكسدة الغذاء وإنتاج الطاقة على شكل حرارة؟ (ص 79، السؤال الثاني)", ["الثيروكسين", "الأنسولين", "الأدرينالين"], 0, 79], ["أيّ الغدد يسيطر على عمل جميع الغدد الصماء؟ (ص 63)", ["الغدة النخامية", "الغدة الدرقية", "الغدة الكظرية"], 0, 63], ["ما اسم الجزء من البنكرياس الذي يفرز الأنسولين والغلوكاغون؟ (ص 80، السؤال الخامس)", ["جزر لانغرهانز", "قناة البنكرياس", "الاثنا عشر"], 0, 80]]}, {"t": "المستقبلات الحسية", "pg": 1067, "p2": 1, "pts": ["تُعدّ الحواس الخمس مصدرًا مهمًّا للإدراك في الإنسان، ولكل حاسة وظيفة خاصة. (ص 67)", "تتكوّن الأذن من: الأذن الخارجية (صيوان الأذن الذي يجمع الموجات الصوتية، والقناة السمعية المنتهية بغشاء الطبلة)، والأذن الوسطى (المطرقة والسندان والركاب، وقناة استاكيوس التي تساوي الضغط على جانبي الطبلة)، والأذن الداخلية (القوقعة للسمع، والدهليز والقنوات الهلالية لتوازن الجسم). (ص 67–68)", "تتركّب العين من ثلاث طبقات: الخارجية (الصلبة، وجزؤها الأمامي الشفاف القرنية)، والوسطى (المشيمية، والقزحية التي تتحكم بفتحة البؤبؤ وتعطي العين لونها، والجسم الهدبي)، والداخلية (الشبكية وفيها العصي للرؤية في الضوء الخافت والمخاريط لتمييز الألوان). (ص 71–72)", "تسقط الأشعة الضوئية المنعكسة عن الجسم على العين وتنفذ خلال العدسة التي تركّزها على الشبكية مكوّنة صورة مصغّرة ومقلوبة، ويفسّرها مركز الإبصار في المخ على شكل صورة معتدلة. (ص 73)", "يتكوّن الجلد من البشرة والأدمة التي تحتوي نهايات عصبية لمستقبلات حسية للحرارة والألم والضغط. وعلى اللسان خلايا تذوق (براعم) تميّز المذاق (حلو، مالح، حامض، مر). ويمثّل الأنف عضو الاستقبال الشمي. (ص 75–77)"], "terms": [["القوقعة", "جزء من الأذن الداخلية يحتوي خلايا الاستقبال السمعي. (ص 68)"], ["القنوات الهلالية", "ثلاث قنوات تعمل مع الدهليز على حفظ توازن الجسم. (ص 68)"], ["القرنية", "الجزء الأمامي الرقيق الشفاف من الصلبة يسمح بمرور الضوء. (ص 71)"], ["الشبكية", "الطبقة الداخلية للعين وتحتوي المستقبلات الضوئية (العصي والمخاريط). (ص 72)"]], "ex": [["تتبّع مسار الموجات الصوتية حتى الدماغ. (ص 68)", "صيوان الأذن ← القناة السمعية ← غشاء الطبلة ← المطرقة ← السندان ← الركاب ← سائل القوقعة ← العصب السمعي ← مراكز السمع في الدماغ."], ["كيف تحافظ لاعبة الجمباز على توازنها؟ (ص 69، نشاط 4)", "تتأثر مستقبلات التوازن في الدهليز والقنوات الهلالية، فيُنقل سيال عصبي إلى المخيخ الذي يصدر الأوامر للعضلات لإعادة التوازن."], ["فكّر: تقلّ حاستا التذوق والشم عند الإصابة بالرشح أو الزكام. (ص 77)", "لارتباط حاسة الشم بحاسة التذوق ارتباطًا وثيقًا."], ["أيّ أجزاء الأذن يقوم بتجميع الموجات الصوتية؟ (ص 78، س1 فقرة 5) (تمرين من الكتاب، ص 78)", "صيوان الأذن"]], "id": "U7L3", "img": [1067, 1068, 1069, 1070, 1071, 1072, 1073, 1074, 1075, 1076, 1077, 1078, 1079, 1080], "bmc": [["أيّ أجزاء الأذن يقوم بتجميع الموجات الصوتية؟ (ص 78، س1 فقرة 5)", ["صيوان الأذن", "المطرقة", "القوقعة", "القناة السمعية"], 0, 78], ["أُصيب خالد بضربة على خده فشعر بفقدان التوازن. أيّ أجزاء الأذن تأثر؟ (ص 78، س1 فقرة 6)", ["الدهليز والقنوات الهلالية", "الدهليز والقوقعة", "القوقعة والقنوات الهلالية", "القنوات الهلالية والقناة السمعية"], 0, 78], ["في أيّ جزء من الجسم تقع الخلايا الشمية؟ (ص 78، س1 فقرة 7)", ["داخل الوجه وتحت العينين", "داخل الوجه وفوق العينين", "في فتحة الأنف", "المخ"], 0, 78], ["ما اسم الجزء من العين الذي يسمح بمرور الأشعة الضوئية إلى داخلها؟ (ص 78، س1 فقرة 10)", ["القرنية", "العدسة", "الشبكية", "القزحية"], 0, 78], ["ما اسم الجزء من الدماغ الذي يحتوي على مركز الشم؟ (ص 78، س1 فقرة 2)", ["المخ", "المخيخ", "النخاع المستطيل", "تحت المهاد"], 0, 78], ["أيّ أجزاء العين ينظّم كمية الضوء الداخلة إليها؟ (ص 79، السؤال الثاني)", ["البؤبؤ", "الشبكية", "الصلبة"], 0, 79]]}]}, {"id": "U8", "part": 1, "t": "الوحدة الثامنة: الحرارة وأثرها على الأجسام — الجزء الثاني", "les": [{"t": "الحرارة", "pg": 1084, "p2": 1, "pts": ["نشعر بسخونة الجسم أو برودته عند لمسه اعتمادًا على الفرق في درجة الحرارة بينه وبين درجة حرارة اليد. (ص 86)", "تُعرف درجة الحرارة بأنها صفة للمادة تحدّد اتجاه انتقال الطاقة الحرارية بين الأجسام عند تلامسها؛ حيث تنتقل هذه الطاقة من الأجسام الساخنة إلى الأجسام الأقل سخونة. (ص 86)", "كمية الحرارة التي تكتسبها الأجسام أو تفقدها تسبّب ارتفاع درجة حرارتها أو انخفاضها، فكلما كان التغيّر في درجة حرارة جسم ما أكبر كانت كمية الحرارة اللازمة أكبر. والطاقة الحرارية التي يمتلكها جسم تتناسب طرديًّا مع كتلته. (ص 87–88)", "الحرارة النوعية: كمية الحرارة اللازمة لرفع درجة حرارة وحدة الكتل من المادة درجة سلسيوس واحدة. كمية الحرارة المكتسبة أو المفقودة = الكتلة × الحرارة النوعية × التغيّر في درجة الحرارة. (ص 89)", "السعة الحرارية: كمية الطاقة الحرارية اللازمة لرفع درجة حرارة الجسم كله درجة سلسيوس واحدة، وتساوي الكتلة × الحرارة النوعية. (ص 89)", "عند اتصال جسمين مختلفين في درجة حرارتهما تنتقل الطاقة الحرارية من الساخن إلى البارد إلى أن تتساوى درجتا حرارتهما فيكونان في حالة اتزان حراري. (ص 90)"], "terms": [["درجة الحرارة", "صفة للمادة تحدّد اتجاه انتقال الطاقة الحرارية بين الأجسام عند تلامسها. (ص 86)"], ["الحرارة النوعية", "كمية الحرارة اللازمة لرفع درجة حرارة وحدة الكتل من المادة درجة سلسيوس واحدة. (ص 89)"], ["السعة الحرارية", "كمية الطاقة الحرارية اللازمة لرفع درجة حرارة الجسم كله درجة سلسيوس واحدة. (ص 89)"], ["الاتزان الحراري", "تساوي درجتي حرارة جسمين متلامسين بعد انتقال الحرارة بينهما. (ص 90)"]], "ex": [["خاتم ذهب كتلته 20 غم في 25 °س سُخّن إلى 100 °س. ما كمية الحرارة التي اكتسبها (الحرارة النوعية للذهب 125 جول/كغم.°س)؟ (ص 89)", "ك ح = 0,02 × 125 × (100 − 25) = 187,5 جول"], ["احسب السعة الحرارية لقطعة خشب كتلتها 100 غم وحرارتها النوعية 1672 جول/كغم.°س. (ص 90)", "السعة الحرارية = 0,1 × 1672 = 167,2 جول/°س"], ["احسب السعة الحرارية لخاتم الذهب في المثال الأول. (ص 90، سؤال)", "0,02 × 125 = 2,5 جول/°س"], ["كرة حديد كتلتها 300 غرام بردت من 175 °س إلى 25 °س. احسب الحرارة المفقودة (الحرارة النوعية للحديد 460 جول/كغم.°س). (ص 99، السؤال الثاني)", "ك ح = 0,3 × 460 × 150 = 20700 جول"]], "id": "U8L1", "img": [1084, 1085, 1086, 1087, 1088, 1089, 1090], "bmc": [["ماذا نطلق على صفة المادة التي تحدّد اتجاه انتقال الطاقة الحرارية بين الأجسام عند تلامسها؟ (ص 97، س1 فقرة 1)", ["درجة الحرارة", "كمية الحرارة", "الحرارة النوعية", "السعة الحرارية"], 0, 97], ["أيّ الوحدات الآتية تُستخدم لقياس كمية الحرارة؟ (ص 97، س1 فقرة 3)", ["جول", "جول/°س", "جول/كغم", "جول/ثانية"], 0, 97], ["ما قيمة السعة الحرارية لكمية من الماء كتلتها 100 غم، علمًا أن حرارته النوعية 4000 جول/كغم.°س؟ (ص 97، س1 فقرة 4)", ["400 جول/°س", "100 جول/°س", "4000 جول/°س", "4400 جول/°س"], 0, 97], ["أيّ العوامل الآتية لا يؤثر في كمية الحرارة التي يكتسبها جسم عند رفع درجة حرارته بمقدار معيّن؟ (ص 98، س1 فقرة 10)", ["درجة حرارة الجسم قبل التسخين", "كتلة الجسم", "مقدار الارتفاع في درجة الحرارة", "نوع مادة الجسم"], 0, 98], ["إناء نحاس كتلته 0,04 كغم في 25 °س اكتسب 1200 جول (الحرارة النوعية 400 جول/كغم.°س). إلى أيّ درجة يصل؟ (ص 99، السؤال الرابع)", ["100 °س", "75 °س", "50 °س"], 0, 99]]}, {"t": "المواد الموصلة والمواد العازلة للحرارة", "pg": 1091, "p2": 1, "pts": ["تختلف المواد في قدرتها على توصيل الحرارة؛ فهناك مواد جيدة التوصيل للحرارة مثل النحاس والألومنيوم والحديد، ومواد رديئة التوصيل مثل البلاستيك والزجاج والخشب والغازات. (ص 92)", "تنتقل الحرارة في الأجسام الصلبة بطريقة التوصيل الحراري من الطرف الأكثر سخونة إلى الطرف الأقل سخونة. كما تنتقل الحرارة بالإشعاع، وبهذه الطريقة تنتقل الطاقة الحرارية من الشمس إلى الأرض. (ص 93)", "تنتقل الحرارة في الموائع (السوائل والغازات) بطريقة الحمل؛ فإذا سُخّن المائع فإنه يتمدد فتقلّ كثافته ويرتفع إلى أعلى. (ص 95)", "الاحتباس الحراري: نتيجة زيادة انبعاث غازات الاحتراق (ثاني أكسيد الكربون وبخار الماء والميثان) يحتفظ الغلاف الجوي بالأشعة المنبعثة من سطح الأرض فترتفع درجة حرارة سطحها. ومن أسبابه النشاطات البشرية كحرق الفحم وقطع الأشجار. (ص 95)", "تتمدد المواد بارتفاع درجة حرارتها وتتقلص بانخفاضها. ويشذّ الماء عن هذه القاعدة في درجات الحرارة التي تقل عن 4 °س فيتمدد بالبرودة وتقلّ كثافته، وتُسمّى هذه الظاهرة شذوذ الماء. (ص 96)"], "terms": [["التوصيل الحراري", "انتقال الحرارة في الأجسام الصلبة من الطرف الأكثر سخونة إلى الأقل سخونة. (ص 93)"], ["الحمل", "انتقال الحرارة في الموائع بتمدد المائع الساخن وارتفاعه. (ص 95)"], ["الإشعاع", "انتقال الطاقة الحرارية كما من الشمس إلى الأرض. (ص 93)"], ["الاحتباس الحراري", "ارتفاع درجة حرارة سطح الأرض لاحتفاظ الغلاف الجوي بالأشعة المنبعثة منه. (ص 95)"], ["شذوذ الماء", "تمدد الماء بالبرودة وتقلّصه بالسخونة دون 4 °س. (ص 96)"]], "ex": [["فكّر: تُصنع أواني الطبخ من فلز بينما تُصنع مقابضها من البلاستيك. (ص 92)", "لأن الفلز جيد التوصيل للحرارة، والبلاستيك رديء التوصيل."], ["عند تسخين طرف قضيب معدني ثُبّتت عليه عيدان بالشمع، أيّ العيدان يسقط أولًا؟ (ص 93، نشاط 4)", "الأقرب إلى المصدر الحراري؛ لأن الحرارة تنتقل بالتوصيل من الطرف الساخن إلى الطرف الآخر."], ["فسّر: تُترك مسافات فارغة بين قضبان سكة الحديد. (ص 99، السؤال السادس)", "لأن المواد تتمدد بارتفاع درجة حرارتها."], ["فكّر: تستطيع بعض الحيوانات العيش في المحيطات المتجمدة. (ص 96)", "بسبب شذوذ الماء؛ إذ يكون الماء عند 4 °س أعلى كثافة في القاع ويتجمد السطح."]], "id": "U8L2", "img": [1091, 1092, 1093, 1094, 1095, 1096, 1097, 1098, 1099, 1100], "bmc": [["أيّ من المواد الآتية يُعدّ جيد التوصيل للحرارة؟ (ص 97، س1 فقرة 2)", ["النحاس", "الخشب", "البلاستيك", "الهواء"], 0, 97], ["أيّ الصيغ الكيميائية الآتية يسبب ظاهرة الاحتباس الحراري؟ (ص 97، س1 فقرة 5)", ["CO2", "N2", "O2", "H2"], 0, 97], ["ماذا يُطلق على طريقة انتقال الطاقة من الشمس إلى الأرض وبسرعة الضوء؟ (ص 98، س1 فقرة 6)", ["الإشعاع", "التوصيل", "الحمل", "الضغط"], 0, 98], ["عند أيّ درجة حرارة تبدأ ظاهرة شذوذ الماء بالتبريد؟ (ص 98، س1 فقرة 7)", ["4 °س", "صفر °س", "−4 °س", "5 °س"], 0, 98], ["ماذا يحدث لحجم عينة من الماء درجة حرارتها 2 °س إذا تم تسخينها؟ (ص 98، س1 فقرة 8)", ["يقلّ ثم يزيد", "يقلّ", "يزداد ثم يقلّ", "يزداد"], 0, 98], ["ما طريقة انتقال الحرارة في السوائل؟ (ص 98، س1 فقرة 9)", ["الحمل", "الإشعاع", "التوصيل", "الحمل والتوصيل"], 0, 98]]}]}];
